header.css:
header{position:fixed;top:0;left:0;right:0;z-index:100;transition:background .4s,box-shadow .4s,padding .4s;padding:18px 0}
header.scrolled{background:#fff;box-shadow:0 6px 22px -14px rgba(2,40,58,.45);padding:10px 0}
.nav{display:flex;align-items:center;justify-content:space-between;gap:20px}
.brand{display:flex;align-items:center;gap:11px;font-family:'Varela Round',var(--body);font-weight:400;font-size:1.06rem;letter-spacing:.01em;color:#fff;transition:color .4s;flex-shrink:0}
header.scrolled .brand{color:var(--deep)}
/* white coin keeps the full-colour ball legible while the bar is transparent */
.brand .ball{height:42px;width:42px;display:grid;place-items:center;border-radius:50%;background:#fff;padding:4px;box-shadow:0 2px 12px rgba(2,40,58,.22);transition:background .4s,box-shadow .4s,padding .4s}
header.scrolled .brand .ball{background:transparent;box-shadow:none;padding:0}
.brand .ballimg{height:100%;width:100%;object-fit:contain}
.brand span{max-width:150px;line-height:1.12}
.nav-links{display:flex;align-items:center;gap:26px;font-size:.9rem;font-weight:500}
.nav-links>a{color:rgba(255,255,255,.94);transition:color .3s;position:relative;background:none;border:none;font:inherit;cursor:pointer;display:inline-flex;align-items:center;gap:5px;padding:6px 0}
header.scrolled .nav-links>a{color:var(--navlink)}
.nav-links>a::after{content:"";position:absolute;left:0;bottom:0;width:0;height:2px;background:var(--teal);transition:width .3s}
.nav-links>a:hover::after{width:100%}
.nav-right{display:flex;align-items:center;gap:18px;flex-shrink:0}
.signin{font-size:.9rem;font-weight:500;color:rgba(255,255,255,.94);transition:color .3s;white-space:nowrap}
.signin:hover{color:#fff;text-decoration:underline;text-underline-offset:4px}
header.scrolled .signin{color:var(--navlink)}
header.scrolled .signin:hover{color:var(--deep)}
.nav-cta{padding:.62em 1.4em;font-size:.9rem;border-radius:999px;font-weight:600;white-space:nowrap;background:var(--mint);color:var(--deep2);transition:transform .25s,box-shadow .25s,background .35s,color .35s}
.nav-cta:hover{transform:translateY(-2px);box-shadow:0 10px 24px -10px rgba(0,0,0,.35)}
header.scrolled .nav-cta{background:var(--btnblue);color:#fff}
.menu-btn{display:none;background:none;border:none;cursor:pointer;flex-direction:column;gap:5px;padding:6px}
.menu-btn span{width:24px;height:2px;background:#fff;transition:background .4s}
header.scrolled .menu-btn span{background:var(--navlink)}

