footer.css:
footer{background:var(--btnblue);color:#fff;padding:64px 0 36px}
.foot-top{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:36px;padding-bottom:40px;border-bottom:1px solid rgba(255,255,255,.3)}
.foot-brand{display:flex;align-items:center;gap:12px;margin-bottom:18px}
.foot-brand .ball{height:46px;width:46px;display:grid;place-items:center;background:#fff;border-radius:50%;padding:4px;box-shadow:0 2px 12px rgba(2,40,58,.2)}
.foot-brand .ballimg{height:100%;width:100%;object-fit:contain}
.foot-brand span{font-family:'Varela Round',var(--body);color:#fff;font-size:1.12rem}
.foot-tag{font-family:var(--display);font-style:italic;font-size:1.25rem;color:#fff;max-width:22ch;line-height:1.35}
.foot-col h4{color:#fff;font-size:.78rem;letter-spacing:.16em;text-transform:uppercase;margin-bottom:16px;font-weight:600}
.foot-col a{display:block;margin-bottom:10px;font-size:.95rem;transition:color .25s}
.foot-col a:hover{color:var(--accent-mint)}
.foot-bottom{padding-top:26px;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;font-size:.84rem;color:rgba(255,255,255,.92)}
/* WJ: clickable social icons. Seams: data-link="linkedin|instagram|facebook|youtube" */
.foot-social{display:flex;align-items:center;gap:12px;margin-top:4px}
.foot-social a{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;
  background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.34);color:#fff;
  transition:background .25s,transform .25s}
.foot-social a:hover{background:#fff;color:var(--btnblue);transform:translateY(-2px)}
.foot-social svg{width:17px;height:17px;fill:currentColor;display:block}

