   --light = white wordmark + white coin behind the mark (coin ratio 1.08). --dark = grey wordmark, no coin, for the white scrolled bar.
   The coin is REQUIRED on any dark or blue ground: the mark's #0190BE against the footer's
   #0090be measures 1.000:1 and 44.6% of the mark disappears without it. */
.brand{display:grid;flex-shrink:0;line-height:0}
.brand img{grid-area:1/1;height:54px;width:auto;display:block;transition:opacity .4s,height .4s}
.brand-logo--dark{opacity:0}
header.scrolled .brand-logo--light{opacity:0}
header.scrolled .brand-logo--dark{opacity:1}
header.scrolled .brand img{height:47px}
.nav-links{display:flex;align-items:center;gap:26px;font-size:.9rem;font-weight:500}
.nav-links>a{color:rgba(255,255,255,.94);transition:color .3s;position:relative;background:none;border:none;font:inherit;cursor:pointer;display:inline-flex;align-items:center;gap:5px;padding:6px 0}
