.signin{font-size:.9rem;font-weight:500;color:rgba(255,255,255,.94);transition:color .3s;white-space:nowrap}
.signin:hover{color:#fff;text-decoration:underline;text-underline-offset:4px}
header.scrolled .signin{color:var(--navlink)}
header.scrolled .signin:hover{color:var(--deep)}
.nav-cta{padding:.62em 1.4em;font-size:.9rem;border-radius:999px;font-weight:600;white-space:nowrap;background:var(--mint);color:var(--deep2);transition:transform .25s,box-shadow .25s,background .35s,color .35s}
.nav-cta:hover{transform:translateY(-2px);box-shadow:0 10px 24px -10px rgba(0,0,0,.35)}
header.scrolled .nav-cta{background:var(--btnblue);color:#fff}
.menu-btn{display:none;background:none;border:none;cursor:pointer;flex-direction:column;gap:5px;padding:6px}
.menu-btn span{width:24px;height:2px;background:#fff;transition:background .4s}
header.scrolled .menu-btn span{background:var(--navlink)}

/* --- FOOTER --- */
footer{background:var(--btnblue);color:#fff;padding:64px 0 36px}
.foot-top{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:36px;padding-bottom:40px;border-bottom:1px solid rgba(255,255,255,.3)}
.foot-brand{margin-bottom:18px;line-height:0}
.foot-brand img{height:73px;width:auto;display:block}
.foot-tag{font-family:var(--display);font-style:italic;font-size:1.25rem;color:#fff;max-width:22ch;line-height:1.35}
.foot-col h4{color:#fff;font-size:.78rem;letter-spacing:.16em;text-transform:uppercase;margin-bottom:16px;font-weight:600}
.foot-col a{display:block;margin-bottom:10px;font-size:.95rem;transition:color .25s}
.foot-col a:hover{color:var(--accent-mint)}
.foot-bottom{padding-top:26px;display:flex;flex-direction:column;align-items:stretch;gap:10px;font-size:.84rem;line-height:1.55;color:rgba(255,255,255,.92);text-align:left}
.foot-legal{display:block;width:100%}
.foot-copy{display:block;width:100%;color:rgba(255,255,255,.78)}
/* WJ: clickable social icons. Seams: data-link="linkedin|instagram|facebook|youtube" */
.foot-social{display:flex;align-items:center;gap:12px;margin-top:4px}
.foot-social a{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;
  background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.34);color:#fff;
  transition:background .25s,transform .25s}
.foot-social a:hover{background:#fff;color:var(--btnblue);transform:translateY(-2px)}
.foot-social svg{width:17px;height:17px;fill:currentColor;display:block}

/* --- responsive: drop these into your existing breakpoints --- */
@media(max-width:900px){
  .nav-links{display:none}
  .menu-btn{display:flex}
  .foot-top{grid-template-columns:1fr 1fr;gap:30px}
}
@media(max-width:600px){
  .foot-top{grid-template-columns:1fr}
}


